  if exists(select 1 from storage.buckets where id='campus-portfolio-private') then raise exception 'Existing campus portfolio bucket: inspect and back up before any action'; end if;
  if exists(select 1 from pg_policies where schemaname='realtime' and tablename='messages' and policyname='campus_space_actor_receive') then raise exception 'Existing shared-facility policy: campus_space_actor_receive'; end if;
  if exists(select 1 from pg_policies where schemaname='realtime' and tablename='messages' and policyname='campus_space_actor_send') then raise exception 'Existing shared-facility policy: campus_space_actor_send'; end if;
