  if exists(select 1 from pg_policies where schemaname='realtime' and tablename='messages' and policyname='campus_space_send_guard') then raise exception 'Existing shared-facility policy: campus_space_send_guard'; end if;
  if exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='campus_portfolio_server_read_only') then raise exception 'Existing shared-facility policy: campus_portfolio_server_read_only'; end if;
  if exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='campus_portfolio_server_update_only') then raise exception 'Existing shared-facility policy: campus_portfolio_server_update_only'; end if;
  if exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='campus_portfolio_server_delete_only') then raise exception 'Existing shared-facility policy: campus_portfolio_server_delete_only'; end if;
end;
